/**
 * 宿主归一化：
 * - 原始酒馆预设中的空槽位依赖酒馆运行时注入，项目已经由自己的世界书/玩家档案管线提供，不能继续作为空条目展示。
 * - assistant 条目是酒馆的示例/预填充协议；项目统一以 system 提示提交，避免部分 API 拒绝尾部 assistant 消息而直接中止请求。
 * - 酒馆把 chatHistory 之后的模块（order ≥ 720）逐条投在聊天历史末端，贴近生成点；压进系统提示头部会明显降低遵循率。
 */
export const DRC_TAIL_INJECTION_MIN_ORDER = 720;

export const DRC_V12_PROMPTS: PresetPromptEntry[] = DRC_LOCALIZED_PROMPTS
  .filter(entry => entry.content.trim().length > 0)
  .map(entry => {
    const normalized: PresetPromptEntry = entry.role === 'assistant' ? { ...entry, role: 'system' as const } : entry;
    if (normalized.order < DRC_TAIL_INJECTION_MIN_ORDER && normalized.injectionPosition !== 1) return normalized;
    return {
      ...normalized,
      ...(normalized.injectionPosition === 1 ? {} : { injectionPosition: 1 as const, injectionDepth: 0 }),
      injectionLabel: normalized.injectionLabel ?? normalized.name,
    };
  });

